  place({ part: '15068', at: [2, 32, -2], colour: 'dRed', turn: 270 }),

  // Pelvis & Lower Torso
  place({ part: '3020', at: [-2, 33, -1], colour: 'dRed' }),
  place({ part: '3795', at: [-3, 34, -2], colour: 'dRed' }),
  place({ part: '3020', at: [-2, 35, -2], colour: 'belly' }),
