  const wedge3 = isLeft ? '43723a' : '43722a'; // Left vs Right 2x3
  const turnVal = isLeft ? 0 : 0;
  const ops = [];

  // Main Wing Spar (bone arm extending up and outward)
  const xRoot = isLeft ? -3 : 2;
  ops.push(place({ part: '3021', at: [xRoot, 41, -2], colour: 'dRed' }));

  const xMid = isLeft ? -6 : 4;
