  ops.push(place({ part: '11477', at: [xMid, 44, -1], colour: 'red', turn: isLeft ? 90 : 270 }));

  const xOuter = isLeft ? -10 : 7;
  ops.push(place({ part: '3795', at: [xOuter, 46, 0], colour: 'dRed' }));
  ops.push(place({ part: '11477', at: [xOuter, 47, 0], colour: 'red', turn: isLeft ? 90 : 270 }));

  const xTip = isLeft ? -14 : 11;
  ops.push(place({ part: '3020', at: [xTip, 49, 1], colour: 'dRed' }));
  ops.push(place({ part: '54200', at: [xTip + (isLeft ? -1 : 3), 50, 1], colour: 'gold', turn: isLeft ? 90 : 270 }));

  // Wing Membrane Vanes (stepped scalloped plates)
  // Vane 1 (Top / Outer)
  ops.push(place({ part: wedge4, at: [isLeft ? -14 : 12, 48, 2], colour: 'red', turn: turnVal }));
  ops.push(place({ part: '51739', at: [isLeft ? -12 : 8, 48, 3], colour: 'dRed' }));

  // Vane 2 (Middle)
  ops.push(place({ part: wedge3, at: [isLeft ? -10 : 8, 45, 1], colour: 'red', turn: turnVal }));
  ops.push(place({ part: '3020', at: [isLeft ? -8 : 4, 45, 2], colour: 'dRed' }));
  ops.push(place({ part: '3069b', at: [isLeft ? -8 : 6, 46, 2], colour: 'dRed' }));

  // Vane 3 (Inner / Lower)
  ops.push(place({ part: wedge3, at: [isLeft ? -6 : 4, 42, 0], colour: 'red', turn: turnVal }));
  ops.push(place({ part: '3021', at: [isLeft ? -5 : 2, 42, 1], colour: 'dRed' }));

  // Trailing edge claws/spines
  ops.push(place({ part: '54200', at: [isLeft ? -14 : 13, 49, 3], colour: 'gold', turn: 180 }));
  ops.push(place({ part: '54200', at: [isLeft ? -10 : 9, 46, 2], colour: 'gold', turn: 180 }));
  ops.push(place({ part: '54200', at: [isLeft ? -6 : 5, 43, 1], colour: 'gold', turn: 180 }));

  return ops;
}

