  place({ part: '18395', at: [-1, 48, -14], colour: 'fireO' }),
  place({ part: '64647', at: [0, 49, -15], colour: 'fireR' }),
  place({ part: '54200', at: [-1, 49, -16], colour: 'fireY', turn: 0 }),
  place({ part: '54200', at: [0, 49, -16], colour: 'fireO', turn: 0 })
]);

// 5. Long Sinuous Tail with Barbed Spade Tip
section('DragonTail', [
